-- 云端兼容版：保留业务 UUID 主键；RLS 从“auth.uid() 直接等于业务 UUID”改为
-- 通过 profiles.openid 映射云端 auth.uid() 字符串到业务 UUID。
CREATE TABLE IF NOT EXISTS public.message_visibility (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  message_id UUID NOT NULL REFERENCES public.messages(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (message_id, user_id)
);

ALTER TABLE public.message_visibility ENABLE ROW LEVEL SECURITY;

CREATE POLICY users_select_message_visibility ON public.message_visibility
  FOR SELECT USING (
    user_id IN (SELECT id FROM public.profiles WHERE openid = auth.uid())
  );

CREATE POLICY senders_insert_message_visibility ON public.message_visibility
  FOR INSERT WITH CHECK (
    user_id IN (SELECT id FROM public.profiles WHERE openid = auth.uid())
    AND EXISTS (
      SELECT 1 FROM public.messages m
      WHERE m.id = message_id
        AND m.sender_id IN (SELECT id FROM public.profiles WHERE openid = auth.uid())
    )
  );

CREATE POLICY users_delete_message_visibility ON public.message_visibility
  FOR DELETE USING (
    user_id IN (SELECT id FROM public.profiles WHERE openid = auth.uid())
  );

CREATE INDEX IF NOT EXISTS idx_message_visibility_user_id
  ON public.message_visibility (user_id);

CREATE INDEX IF NOT EXISTS idx_message_visibility_message_id
  ON public.message_visibility (message_id);